  Pharma_addProgramBeneficiaryToProduct(
    input: {
      origin: POINT_OF_SALES
      # Use o programCode retornado por Pharma_assessEligibility
      programCode: "8"
      storeCode: "00000000000010"
      customerCode: "00000000000"
      productCode: "7896269900150"
      # Preencha com o ID retornado em dependents; null associa ao titular
